package com.bank.liquidity.model;

// Holds the worst (most negative) drawdown total and its inclusive day range.
public class DrawdownResult {
    private final long total;
    private final int startDay;
    private final int endDay;

    public DrawdownResult(long total, int startDay, int endDay) {
        this.total = total;
        this.startDay = startDay;
        this.endDay = endDay;
    }

    public long getTotal() { return total; }
    public int getStartDay() { return startDay; }
    public int getEndDay() { return endDay; }

    @Override
    public String toString() {
        return "worstDrawdown=" + total + " days[" + startDay + ".." + endDay + "]";
    }
}
