package com.bank.liquidity.service;

import com.bank.liquidity.model.DrawdownResult;

import java.util.Arrays;
import java.util.logging.Logger;

// Minimum variant of Kadane's algorithm: worst continuous cash drawdown.
public class DrawdownAnalyzer {
    private static final Logger log = Logger.getLogger(DrawdownAnalyzer.class.getName());

    public DrawdownResult worstDrawdown(int[] cashMoves) {
        if (cashMoves == null || cashMoves.length == 0) {
            throw new IllegalArgumentException("Cash movement sequence must be non-empty");
        }
        long currentMin = cashMoves[0];
        long globalMin = cashMoves[0];
        int tentativeStart = 0;
        int bestStart = 0;
        int bestEnd = 0;

        for (int i = 1; i < cashMoves.length; i++) {
            if (currentMin > 0) {
                // Running decline is being helped up: restart a fresh decline.
                currentMin = cashMoves[i];
                tentativeStart = i;
                final int day = i;
                log.fine(() -> "Running sum positive; restarting drawdown at day " + day);
            } else {
                currentMin += cashMoves[i];
            }
            if (currentMin < globalMin) {
                globalMin = currentMin;
                bestStart = tentativeStart;
                bestEnd = i;
            }
        }
        DrawdownResult result = new DrawdownResult(globalMin, bestStart, bestEnd);
        log.info(() -> "Worst drawdown over " + Arrays.toString(cashMoves) + " = " + result);
        return result;
    }
}
